  bundle: ReturnType<typeof getBundleCodec> &
    SelfFetchFunctions<BundleArgs, Bundle>;
  bundleCreatorAccount: ReturnType<typeof getBundleCreatorAccountCodec> &
    SelfFetchFunctions<BundleCreatorAccountArgs, BundleCreatorAccount>;
  bundleMasterAccount: ReturnType<typeof getBundleMasterAccountCodec> &
    SelfFetchFunctions<BundleMasterAccountArgs, BundleMasterAccount>;
  bundleTempData: ReturnType<typeof getBundleTempDataCodec> &
    SelfFetchFunctions<BundleTempDataArgs, BundleTempData>;
