export type NtbundlePluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function ntbundleProgram() {
  return <T extends NtbundlePluginRequirements>(
    client: T,
  ): ExtendedClient<T, { ntbundle: NtbundlePlugin }> => {
    return extendClient(client, {
      ntbundle: <NtbundlePlugin>{
        accounts: {
          bundle: addSelfFetchFunctions(client, getBundleCodec()),
          bundleCreatorAccount: addSelfFetchFunctions(
            client,
            getBundleCreatorAccountCodec(),
          ),
          bundleMasterAccount: addSelfFetchFunctions(
            client,
            getBundleMasterAccountCodec(),
          ),
          bundleTempData: addSelfFetchFunctions(
            client,
            getBundleTempDataCodec(),
          ),
          oracleData: addSelfFetchFunctions(client, getOracleDataCodec()),
          referrerAccount: addSelfFetchFunctions(
            client,
            getReferrerAccountCodec(),
          ),
          strategy: addSelfFetchFunctions(client, getStrategyCodec()),
          userBundleAccount: addSelfFetchFunctions(
            client,
            getUserBundleAccountCodec(),
          ),
        },
        instructions: {
          addStrategy: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAddStrategyInstructionAsync(input),
            ),
          applyFeesToUser: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApplyFeesToUserInstructionAsync(input),
            ),
          changeBundleMasterAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getChangeBundleMasterAdminInstructionAsync(input),
            ),
          changeManager: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getChangeManagerInstruction(input),
            ),
          clearUserFeeOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClearUserFeeOverrideInstructionAsync(input),
            ),
          clearUserWithdrawalTimingOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClearUserWithdrawalTimingOverrideInstructionAsync(input),
            ),
          closeUserBundleAccount: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseUserBundleAccountInstructionAsync(input),
            ),
          distributeToReceivers: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDistributeToReceiversInstructionAsync(input),
            ),
          enableStrategy: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEnableStrategyInstructionAsync(input),
            ),
          endDistribution: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEndDistributionInstructionAsync(input),
            ),
          initializeBundle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeBundleInstructionAsync(input),
            ),
          initializeBundleDepositor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeBundleDepositorInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initializeBundleMasterAccount: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeBundleMasterAccountInstructionAsync(input),
            ),
          initializePermissionedBundleDepositor: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializePermissionedBundleDepositorInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          managerWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManagerWithdrawInstructionAsync(input),
            ),
          managerWithdrawWithSplit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getManagerWithdrawWithSplitInstructionAsync(input),
            ),
          netPendingTransactions: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getNetPendingTransactionsInstructionAsync(input),
            ),
          pauseDepositsWithdrawals: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPauseDepositsWithdrawalsInstructionAsync(input),
            ),
          performRefill: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPerformRefillInstructionAsync(input),
            ),
          processDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProcessDepositInstructionAsync(input),
            ),
          processReferrerWithdrawal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProcessReferrerWithdrawalInstructionAsync(input),
            ),
          processSwitch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProcessSwitchInstructionAsync(input),
            ),
          processWithdrawal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getProcessWithdrawalInstructionAsync(input),
            ),
          referrerRequestWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReferrerRequestWithdrawInstructionAsync(input),
            ),
          refundDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRefundDepositInstructionAsync(input),
            ),
          registerReferrer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterReferrerInstructionAsync(input),
            ),
          removeStrategy: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRemoveStrategyInstructionAsync(input),
            ),
          requestBundleSwitch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestBundleSwitchInstructionAsync(input),
            ),
          requestDeposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestDepositInstructionAsync(input),
            ),
          requestWithdrawal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestWithdrawalInstructionAsync(input),
            ),
          setBundleCreator: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetBundleCreatorInstructionAsync(input),
            ),
          setDelays: (input) =>
            addSelfPlanAndSendFunctions(client, getSetDelaysInstruction(input)),
          setFees: (input) =>
            addSelfPlanAndSendFunctions(client, getSetFeesInstruction(input)),
          setKeeper: (input) =>
            addSelfPlanAndSendFunctions(client, getSetKeeperInstruction(input)),
          setMaxDepositAmount: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMaxDepositAmountInstruction(input),
            ),
          setMinDepositAmount: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetMinDepositAmountInstruction(input),
            ),
          setOracleBuffer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetOracleBufferInstruction(input),
            ),
          setOracleMaxAge: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetOracleMaxAgeInstruction(input),
            ),
          setOracleUpdateTimeLimit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetOracleUpdateTimeLimitInstruction(input),
            ),
          setReferrerActive: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetReferrerActiveInstruction(input),
            ),
          setReferrerConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetReferrerConfigInstruction(input),
            ),
          setReferrerRateOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetReferrerRateOverrideInstruction(input),
            ),
          setUserFeeOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetUserFeeOverrideInstructionAsync(input),
            ),
          setUserReferrer: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetUserReferrerInstructionAsync(input),
            ),
          setUserWithdrawalTimingOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetUserWithdrawalTimingOverrideInstructionAsync(input),
            ),
          setWithdrawalRedemptionSchedule: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetWithdrawalRedemptionScheduleInstruction(input),
            ),
          startDistribution: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getStartDistributionInstructionAsync(input),
            ),
          updateAllocations: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateAllocationsInstructionAsync(input),
            ),
          updateOracle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateOracleInstructionAsync(input),
            ),
        },
        pdas: {
          strategyAccount: findStrategyAccountPda,
          userBundleAccount: findUserBundleAccountPda,
          oracleData: findOracleDataPda,
          bundleAssetAuthority: findBundleAssetAuthorityPda,
          bundleMasterAccount: findBundleMasterAccountPda,
          closeUserBundleAccountUserBundleAccount:
            findCloseUserBundleAccountUserBundleAccountPda,
          bundleTempData: findBundleTempDataPda,
          bundleCreatorAccount: findBundleCreatorAccountPda,
          bundleAccount: findBundleAccountPda,
          pendingBundleAssetAuthority: findPendingBundleAssetAuthorityPda,
          sourceUserBundleAccount: findSourceUserBundleAccountPda,
          sourceBundleAssetAuthority: findSourceBundleAssetAuthorityPda,
          sourceBundleTempData: findSourceBundleTempDataPda,
          sourceOracleData: findSourceOracleDataPda,
          targetUserBundleAccount: findTargetUserBundleAccountPda,
          targetBundleTempData: findTargetBundleTempDataPda,
          targetPendingBundleAssetAuthority:
            findTargetPendingBundleAssetAuthorityPda,
          targetOracleData: findTargetOracleDataPda,
          referrerAccount: findReferrerAccountPda,
          referrerUserBundleAccount: findReferrerUserBundleAccountPda,
          requestBundleSwitchUserBundleAccount:
            findRequestBundleSwitchUserBundleAccountPda,
        },
        identifyAccount: identifyNtbundleAccount,
        identifyInstruction: identifyNtbundleInstruction,
        parseInstruction: parseNtbundleInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
